function validate([sentence]) {
  if (typeof sentence !== 'string' || sentence.length < 1 || sentence.length > 150) return 'sentence has 1 to 150 characters.';
  if (!/^[A-Za-z]+( [A-Za-z]+)*$/.test(sentence)) return 'Use letter-only words separated by single spaces, with no space at either end.';
  return null;
}

