function toGoatLatin(sentence) {
  const vowels = new Set(['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U']);
  const words = sentence.split(' ');
  const result = [];
  let suffix = 'a';
  for (const word of words) {
    let goat;
    if (vowels.has(word[0])) {
      goat = word + 'ma';
    } else {
      goat = word.slice(1) + word[0] + 'ma';
    }
    result.push(goat + suffix);
    suffix += 'a';
  }
  return result.join(' ');
}

