function toGoatLatin(sentence) {
  // Scan character by character, cutting a word at each space or at the end.
  let out = '';
  let position = 0;
  let start = 0;
  for (let p = 0; p <= sentence.length; p++) {
    if (p < sentence.length && sentence.charAt(p) !== ' ') continue;
    const word = sentence.substring(start, p);
    position++;
    const moved = /^[aeiou]/i.test(word) ? word : word.substring(1) + word.charAt(0);
    out += (position > 1 ? ' ' : '') + moved + 'ma' + 'a'.repeat(position);
    start = p + 1;
  }
  return out;
}

