function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const vowels = 'aeiouAEIOU';
  const limit = size === 'large' ? 140 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 30);
  const longest = size === 'large' && rand() < 0.3 ? 2 : 8;
  const words = [];
  let length = -1;
  for (;;) {
    const wordLength = 1 + Math.floor(rand() * longest);
    if (words.length && length + 1 + wordLength > limit) break;
    // Start with a vowel often, since vowel and consonant words follow different rules.
    let word = rand() < 0.4 ? vowels[Math.floor(rand() * vowels.length)] : letters[Math.floor(rand() * letters.length)];
    while (word.length < wordLength) word += letters[Math.floor(rand() * letters.length)];
    words.push(word);
    length += 1 + wordLength;
    if (length >= limit) break;
  }
  return [words.join(' ')];
}
